package plan

import (
	"fmt"
	"sort"
	"strings"

	"github.com/akarachen/sandboxed-agent-builder/internal/plugin"
	"github.com/akarachen/sandboxed-agent-builder/internal/spec"
)

// entrypoint is /usr/local/bin/agent-entrypoint: it installs the caller's
// Codex credentials, runs the packaged startup scripts in order on every
// container start, and only then hands the container to oar. A failing
// startup script stops the container before Codex starts.
const entrypoint = `#!/bin/sh
# agent-entrypoint, runtime contract 1 (generated by sandboxed-agent-builder).
#
#   docker run [-e CODEX_AUTH_JSON_FILE=/run/secrets/codex-auth.json | -e OPENAI_API_KEY=...] \
#     -e AGENT_API_TOKEN=... -p 8080:8080 IMAGE      # the agent control API (default)
#   docker run ... IMAGE run codex "prompt"            # or any oar command line
set -eu

: "${CODEX_HOME:=$HOME/.codex}"
export CODEX_HOME
mkdir -p "$CODEX_HOME"

# Runtime credentials come from the caller, never from the image.
if [ -n "${CODEX_AUTH_JSON_FILE:-}" ]; then
  cp "$CODEX_AUTH_JSON_FILE" "$CODEX_HOME/auth.json"
  chmod 600 "$CODEX_HOME/auth.json"
elif [ -n "${OPENAI_API_KEY:-}" ] && [ ! -f "$CODEX_HOME/auth.json" ]; then
  printenv OPENAI_API_KEY | codex login --with-api-key >/dev/null
fi

for script in /opt/agent/startup/*.sh; do
  [ -e "$script" ] || continue
  name=$(basename "$script")
  echo "agent-entrypoint: startup $name" >&2
  if ! /bin/sh -e "$script"; then
    echo "agent-entrypoint: startup script $name failed; Codex was not started" >&2
    exit 70
  fi
done

if [ "${1:-}" = serve ]; then
  shift
  exec node /opt/agent/server/src/main.js "$@"
fi
exec oar "$@"
`

const (
	agentUID = 1000
	homeDir  = "/home/agent"
)

func dockerfile(r spec.Resolved, plugins []*plugin.Plugin) (string, []string) {
	alpine := r.Base.Family == spec.FamilyAlpine
	codex := r.Agent.Codex // Write checked the agent is Codex.
	var b strings.Builder
	w := func(format string, args ...any) { fmt.Fprintf(&b, format+"\n", args...) }

	w("# Generated by sandboxed-agent-builder, runtime contract %d.", Contract)
	w("# Platform %s; base %s.", r.Platform, r.Base.Ref())
	w("")
	w("# akhook, the hook runtime, from its locked commit: a static musl binary.")
	w("FROM %s AS akhook", r.Akhook.Toolchain.Ref())
	w("RUN apk add --no-cache git build-base")
	w("RUN git init -q /src && cd /src && git remote add origin %s \\", shellQuote(r.Akhook.Repository))
	w("    && git fetch -q --depth 1 origin %s && git checkout -q --detach FETCH_HEAD \\", r.Akhook.Commit)
	w("    && test \"$(git rev-parse HEAD)\" = %s", r.Akhook.Commit)
	w("RUN --mount=type=cache,id=sab-cargo-registry,target=/usr/local/cargo/registry \\")
	w("    cd /src && cargo build -q --release --locked && install -m 0755 target/release/akhook /akhook && /akhook --version")
	w("")
	w("# Node.js %s, checked against the release's SHASUMS256.", r.Node.Version)
	w("FROM %s AS node", r.Base.Ref())
	w("ADD --checksum=sha256:%s %s /node.tar.gz", r.Node.SHA256, r.Node.URL)
	w("RUN mkdir /node && tar -xzf /node.tar.gz -C /node --strip-components=1 --no-same-owner \\")
	w("    && rm -rf /node/include /node/share/doc /node/CHANGELOG.md /node/README.md /node/LICENSE")
	w("")
	w("FROM %s", r.Base.Ref())
	w("SHELL [\"/bin/sh\", \"-eu\", \"-c\"]")
	if alpine {
		w("RUN apk add --no-cache ca-certificates git libstdc++ \\")
		w("    && addgroup -g %d agent && adduser -D -u %d -G agent -h %s -s /bin/sh agent \\", agentUID, agentUID, homeDir)
	} else {
		w("RUN apt-get update && apt-get install -y --no-install-recommends ca-certificates git \\")
		w("    && rm -rf /var/lib/apt/lists/* \\")
		w("    && groupadd -g %d agent && useradd -m -u %d -g agent -d %s -s /bin/sh agent \\", agentUID, agentUID, homeDir)
	}
	w("    && mkdir -p /workspace /opt/agent/startup %s/.codex %s %s && chown agent:agent /workspace %s/.codex", homeDir, plugin.SkillsDir, plugin.ImageRoot, homeDir)
	w("COPY --from=node /node /usr/local")
	w("RUN test \"$(node --version)\" = v%s", r.Node.Version)
	w("COPY --from=akhook /akhook /usr/local/bin/akhook")
	w("RUN npm install -g --no-fund --no-audit --omit=dev %s@%s %s@%s && npm cache clean --force \\",
		codex.Package, codex.Version, r.Oar.Package, r.Oar.Version)
	w("    && test \"$(codex --version)\" = \"codex-cli %s\" \\", codex.Version)
	w("    && test \"$(node -p \"require('$(npm root -g)/%s/package.json').version\")\" = %s \\", r.Oar.Package, r.Oar.Version)
	w("    && oar list >/dev/null && rm -rf /tmp/node-compile-cache")
	w("# The agent control API (Hono), on the oar library the oar CLI installed.")
	w("COPY agent-server /opt/agent/server")
	w("RUN cd /opt/agent/server && npm ci --omit=dev --no-fund --no-audit && npm cache clean --force \\")
	w("    && mkdir -p node_modules/@botiverse \\")
	w("    && ln -s \"$(npm root -g)/%s/node_modules/@botiverse/oar\" node_modules/@botiverse/oar \\", r.Oar.Package)
	w("    && test \"$(node -p \"require('/opt/agent/server/node_modules/@botiverse/oar/package.json').version\")\" = %s \\", r.Oar.Version)
	w("    && node -e \"import('/opt/agent/server/src/app.js')\" && rm -rf /tmp/node-compile-cache")
	w("COPY agent/entrypoint.sh /usr/local/bin/agent-entrypoint")
	w("COPY codex/requirements.toml %s/requirements.toml", plugin.CodexSystemDir)
	w("ENV CODEX_HOME=%s/.codex \\", homeDir)
	w("    AKHOOK_ADDITIONAL_CONFIG_PATH=%s", plugin.HooksConfig)
	w("")

	for _, p := range plugins {
		root := plugin.ImageRoot + "/" + p.Name
		w("# Plugin %s %s.", p.Name, p.Version)
		w("COPY plugins/%s %s", p.Name, root)
		if p.Setup {
			w("RUN --mount=type=cache,id=sab-plugin-%s,target=/var/cache/agent-plugins/%s \\", p.Name, p.Name)
			w("    cd %s && PLUGIN_ROOT=%s PLUGIN_CACHE=/var/cache/agent-plugins/%s PLUGIN_BIN=/usr/local/bin \\", root, root, p.Name)
			w("    AXP_PLUGIN_CACHE=/var/cache/agent-plugins/%s AXP_PLUGIN_BIN=/usr/local/bin ./setup", p.Name)
		}
		for _, s := range p.Skills {
			w("COPY plugins/%s/skills/%s %s", p.Name, s.Dir, plugin.SkillDest(p.Name, s))
		}
		w("")
	}

	w("# Codex configuration (plugin MCP servers) and the plugins' akhook rules.")
	w("COPY codex/config.toml %s/config.toml", plugin.CodexSystemDir)
	w("COPY akhook/plugins.yml %s", plugin.HooksConfig)
	w("")

	secretSet := map[string]bool{}
	for i, s := range r.Scripts.Build {
		w("# Build script %d: %s", i+1, oneLine(s.Name))
		mounts := []string{fmt.Sprintf("--mount=type=bind,source=build/%03d.sh,target=/run/agent-build.sh", i+1)}
		ids := append([]string(nil), s.Secrets...)
		sort.Strings(ids)
		for _, id := range ids {
			secretSet[id] = true
			mounts = append(mounts, fmt.Sprintf("--mount=type=secret,id=%s,target=/run/secrets/%s,required=true", id, id))
		}
		w("RUN %s \\", strings.Join(mounts, " "))
		w("    /bin/sh -e /run/agent-build.sh")
	}
	w("")
	w("# Startup scripts run by the entrypoint on every container start, never here.")
	w("COPY agent/startup %s", "/opt/agent/startup")
	w("COPY agent/manifest.json /opt/agent/manifest.json")
	w("USER agent")
	w("WORKDIR /workspace")
	w("ENTRYPOINT [\"/usr/local/bin/agent-entrypoint\"]")
	w("EXPOSE %d", ControlAPIPort)
	w("CMD [\"serve\"]")

	var secrets []string
	for id := range secretSet {
		secrets = append(secrets, id)
	}
	sort.Strings(secrets)
	return b.String(), secrets
}

func shellQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }
